-- Christmas night: publish scene geometry/art only; never modify player or economy tables.
UPDATE catalog_current SET payload=jsonb_set(payload,'{scenes,christmas}',(payload#>'{scenes,christmas}') || '{"bounds":[4,58,96,97],"blockers":[[7,55,24,61],[76,55,93,61],[14,70,32,78],[66,68,90,78],[20,83,32,89],[6,85,10,89],[92,85,96,89]],"entry":[50,88],"art":{"tile":6,"horizon":0.58,"props":[{"id":"market_left","sprite":"stall","x":15,"y":60,"w":20,"h":24,"solid":[7,55,24,61],"depth":60},{"id":"market_right","sprite":"stall","x":85,"y":60,"w":20,"h":24,"solid":[76,55,93,61],"depth":60},{"id":"tree","sprite":"tree","x":23,"y":77,"w":25,"h":48,"solid":[14,70,32,78],"depth":77},{"id":"nativity","sprite":"nativity","x":78,"y":77,"w":29,"h":37,"solid":[66,68,90,78],"depth":77},{"id":"gifts","sprite":"gifts","x":26,"y":88,"w":15,"h":17,"solid":[20,83,32,89],"depth":88},{"id":"lantern_left","sprite":"lantern","x":8,"y":88,"w":5,"h":31,"solid":[6,85,10,89],"depth":88},{"id":"lantern_right","sprite":"lantern","x":94,"y":88,"w":5,"h":31,"solid":[92,85,96,89],"depth":88}],"theme":"christmas-night"},"artVersion":"christmas-night-1","walkPolygons":[[[14,58],[86,58],[96,97],[4,97]]]}'::jsonb || jsonb_build_object('anchors',(payload#>'{scenes,christmas,anchors}') || '{"star":[63,76],"tree":[36,76],"gifts":[36,86],"back":[50,95],"action_hub_christmas":[58,82]}'::jsonb,'npcPoints',(payload#>'{scenes,christmas,npcPoints}') || '{"child":[43,69],"lucia":[63,83]}'::jsonb,'spots',(SELECT jsonb_agg(COALESCE((SELECT jsonb_set(jsonb_set(s,'{3}',n->3),'{4}',n->4) FROM jsonb_array_elements('[["star","⭐","Treo ngôi sao",78,42,"decorate"],["tree","🎄","Trang trí cây thông",23,62,"decorate"],["gifts","🎁","Xếp hộp quà",29,81,"decorate"],["back","🚪","Về sân",50,95,"go","courtyard"],["action_hub_christmas","🙌","Hành động tại đây",58,82,"activity_hub"]]'::jsonb) n WHERE n->>0=s->>0),s)) FROM jsonb_array_elements(payload#>'{scenes,christmas,spots}') s)));
UPDATE catalog_current SET payload=jsonb_set(payload,'{actions}',(SELECT jsonb_agg(CASE WHEN a->>'id'='noel' THEN jsonb_set(a,'{anchor}','[58,82]'::jsonb) ELSE a END) FROM jsonb_array_elements(payload->'actions') a));
UPDATE catalog_current SET version=version+1;
INSERT INTO catalog_publications(version,payload,reason) SELECT version,payload,'Christmas night plaza: independent artwork, walkable paths and stable quest targets' FROM catalog_current;
